<template><div class="mall-page"><el-card shadow="never" class="!border-none"><el-form inline :model="filters"><el-form-item label="分类名称"><el-input v-model="filters.keyword" clearable placeholder="请输入分类名称" /></el-form-item><el-form-item label="分类状态"><el-select v-model="filters.status" clearable placeholder="全部状态"><el-option label="显示" value="显示" /><el-option label="隐藏" value="隐藏" /></el-select></el-form-item><el-form-item><el-button type="primary" @click="page=1">查询</el-button><el-button @click="filters.keyword='';filters.status='';page=1">重置</el-button></el-form-item></el-form></el-card><el-card shadow="never" class="!border-none mt-4"><template #header><div class="heading"><span>商品分类</span><el-button type="primary" @click="openForm()">添加分类</el-button></div></template><el-table :data="paged" stripe><el-table-column prop="id" label="ID" min-width="120" /><el-table-column label="分类图片" width="110"><template #default="{row}"><el-image :src="row.image" class="category-image" fit="cover" /></template></el-table-column><el-table-column prop="name" label="分类名称" min-width="200" /><el-table-column prop="sort" label="排序" min-width="120" /><el-table-column prop="status" label="状态" min-width="120" /><el-table-column label="操作" width="150"><template #default="{row}"><el-button link type="primary" @click="openForm(row)">编辑</el-button><el-button link type="danger" @click="remove(row)">删除</el-button></template></el-table-column></el-table><div class="pagination"><el-pagination v-model:current-page="page" background layout="total,prev,pager,next" :total="filtered.length" /></div></el-card><el-dialog v-model="visible" :title="editing?'编辑分类':'添加分类'" width="500px"><el-form :model="form" label-width="90px"><el-form-item label="分类名称" required><el-input v-model="form.name" /></el-form-item><el-form-item label="分类图片" required><div><div v-if="form.image" class="upload-preview"><el-image :src="form.image" fit="cover" /><el-button circle size="small" type="danger" @click="form.image=''">×</el-button></div><label v-else class="upload-trigger"><input type="file" accept="image/*" @change="uploadImage" /><span>+</span><small>上传1:1图片</small></label></div></el-form-item><el-form-item label="排序"><el-input v-model="form.sort" /></el-form-item><el-form-item label="状态"><el-radio-group v-model="form.status"><el-radio label="显示"/><el-radio label="隐藏"/></el-radio-group></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">确认</el-button></template></el-dialog></div></template>
<script setup lang="ts" name="pointsMallCategory">const filters=reactive({keyword:'',status:''});const page=ref(1);const visible=ref(false);const editing=ref('');const placeholder='https://images.unsplash.com/photo-1544145945-f90425340c7e?auto=format&fit=crop&w=120&h=120&q=80';const form=reactive<any>({name:'',image:'',sort:0,status:'显示'});const categories=reactive<any[]>(['饮料','休闲食品','日用百货','礼品礼盒','家居用品','生活电器'].map((name,i)=>({id:`JFC${1001+i}`,name,image:`https://images.unsplash.com/${['photo-1544145945-f90425340c7e','photo-1505253716362-afaea1d3d1af'][i%2]}?auto=format&fit=crop&w=120&h=120&q=80`,sort:100-i*10,status:i===4?'隐藏':'显示'})));const filtered=computed(()=>categories.filter(r=>(!filters.keyword||r.name.includes(filters.keyword.trim()))&&(!filters.status||r.status===filters.status)));const paged=computed(()=>filtered.value.slice((page.value-1)*10,page.value*10));const openForm=(r?:any)=>{editing.value=r?.id||'';Object.assign(form,r?{...r}:{name:'',image:'',sort:0,status:'显示'});visible.value=true};const uploadImage=(e:Event)=>{const file=(e.target as HTMLInputElement).files?.[0];if(file)form.image=URL.createObjectURL(file)};const save=()=>{if(!form.name.trim()||!form.image)return ElMessage.error('请填写分类名称并上传分类图片');if(editing.value){const r=categories.find(x=>x.id===editing.value);if(r)Object.assign(r,form)}else categories.unshift({...form,id:`JFC${Date.now()}`});visible.value=false;ElMessage.success('分类已保存')};const remove=async(r:any)=>{try{await ElMessageBox.confirm(`确认删除分类“${r.name}”吗？`,'删除确认',{type:'warning'});categories.splice(categories.indexOf(r),1);ElMessage.success('分类已删除')}catch{}}</script><style scoped>.mall-page{min-height:100%}.mall-page :deep(.el-input),.mall-page :deep(.el-select){width:220px}.heading{display:flex;justify-content:space-between;align-items:center}.category-image{width:56px;height:56px;border-radius:6px}.pagination{display:flex;justify-content:flex-end;margin-top:16px}.upload-preview{position:relative;width:100px;height:100px}.upload-preview :deep(.el-image){width:100px;height:100px;border-radius:6px}.upload-preview .el-button{position:absolute;top:-10px;right:-10px}.upload-trigger{display:flex;width:100px;height:100px;flex-direction:column;align-items:center;justify-content:center;border:1px dashed var(--el-border-color);color:var(--el-text-color-secondary);cursor:pointer}.upload-trigger input{display:none}.upload-trigger span{font-size:28px}.upload-trigger small{font-size:12px}</style>
